import {WORDS,GRADES,poolFor,pointsFor,WordDeck,lifetimeFor,advanceFlight} from './engine.mjs';
import {LocalSpeech} from './speech.mjs';
import {ReadingAttempt} from './reading.mjs';
const $=s=>document.querySelector(s);
const speech=new LocalSpeech();
const attempt=new ReadingAttempt();
let vocabularyHelp=true;
const art=['🎈','🪁','🍎','⭐','🫧','🚀','🍓','🦋','🌻','🎁'];
let level=1,mode='timed',duration=90,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state='idle',demo=false,score=0,remaining=90,targets=[],readWords=[],nextId=0,lastTime=0,spawnClock=0,session=0,previewTime=0;
let deck=new WordDeck(level);
const targetLimit=()=>$('#field').clientWidth<950?2:4;
let best={};try{best=JSON.parse(localStorage.getItem('moorwords-best-reading-v4')||'{}');if(!best||typeof best!=='object')best={};}catch{}
const bestKey=()=>`${level}-${mode}-${duration}-${attempt.pauseMs}-${vocabularyHelp?1:0}-${reduced?1:0}`;
function showBest(){$('#best').replaceChildren(document.createTextNode(`${best[bestKey()]||0} `),Object.assign(document.createElement('em'),{textContent:'Punkte'}));}
function status(main,sub){$('#status').textContent=main;if(sub!==undefined)$('#transcript').textContent=sub;}
function updateStats(){const seconds=Math.ceil(remaining);$('#score').textContent=score;$('#timer').textContent=mode==='practice'?'∞':`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function locks(locked){document.querySelectorAll('[data-level]').forEach(b=>b.disabled=locked);$('#settings').disabled=locked;}
function clearTargets(){targets=[];$('#targets').replaceChildren();}
function createTarget(word,x,y,preview=false,slot=null){const el=document.createElement('button');el.type='button';el.className=`target${preview?' preview-target':''}`;el.dataset.tier=word.tier;el.setAttribute('aria-label',`${word.text}, ${pointsFor(word)} Punkte`);el.tabIndex=demo&&!preview?0:-1;const symbol=document.createElement('span');symbol.className='target-art';symbol.textContent=art[Math.floor(Math.random()*art.length)];symbol.setAttribute('aria-hidden','true');const label=document.createElement('span');label.className='word';label.textContent=word.text;el.title=word.focus||word.text;const points=document.createElement('span');points.className='points';points.textContent=`${word.tier>=3?'✦ ':''}+${pointsFor(word)}`;const life=document.createElement('span');life.className='life';life.setAttribute('aria-hidden','true');el.append(symbol,label,points,life);$('#targets').append(el);const t={id:nextId++,word,el,x,y,slot,age:0,phase:Math.random()*6,vx:0,vy:0,turnIn:0,lifetime:lifetimeFor(word),hit:false,preview};el.addEventListener('click',()=>{if(demo&&state==='playing')hit(t);});targets.push(t);measure(t);position(t);return t;}
function measure(t){
  const field=$('#field'),label=t.el.querySelector('.word');label.style.fontSize='';
  const available=Math.max(100,field.clientWidth/(!t.preview&&field.clientWidth>=950?2:1)-24);
  const contentWidth=Math.max(t.el.scrollWidth,label.offsetWidth+8);
  if(contentWidth>available)label.style.fontSize=Math.max(12,parseFloat(getComputedStyle(label).fontSize)*available/contentWidth-1)+'px';
  const halfX=Math.min(50,(t.el.offsetWidth/2+8)/field.clientWidth*100);
  const halfY=Math.min(50,(t.el.offsetHeight/2+8)/field.clientHeight*100);
  t.bounds={left:halfX,right:100-halfX,top:halfY,bottom:100-halfY};
  if(!t.preview&&t.slot!==null){
    const narrow=field.clientWidth<950;
    const row=narrow?t.slot%2:Math.floor(t.slot/2);
    const top=row*50+halfY,bottom=(row+1)*50-halfY;
    t.bounds.top=Math.min(top,(row+.5)*50);t.bounds.bottom=Math.max(bottom,(row+.5)*50);
    if(!narrow){const col=t.slot%2;const left=col*50+halfX,right=(col+1)*50-halfX;t.bounds.left=Math.min(left,(col+.5)*50);t.bounds.right=Math.max(right,(col+.5)*50);}
  }
}
function position(t){const b=t.bounds;t.x=Math.max(b.left,Math.min(b.right,t.x));t.y=Math.max(b.top,Math.min(b.bottom,t.y));t.el.style.left=t.x+'%';t.el.style.top=t.y+'%';t.el.style.setProperty('--life',Math.max(0,1-t.age/t.lifetime));t.el.classList.toggle('expiring',!t.preview&&t.lifetime-t.age<5);}
function preview(){clearTargets();const slots=$('#field').clientWidth<650?[[16,25],[18,76],[80,79]]:[[14,25],[85,40],[18,76],[80,79]];const pool=poolFor(level);slots.forEach(([x,y],i)=>createTarget(pool[Math.floor(i*pool.length/slots.length)],x,y,true));}
function showGrade(){const grade=GRADES.find(g=>g.id===level);$('#grade-title').textContent=`Klasse ${level} · ${grade.name}`;$('#grade-goal').textContent=grade.goal;}
function spawn(){
  const limit=targetLimit();if(targets.length>=limit)return false;
  const word=deck.next();if(!word)return false;
  const slots=limit===2?[[30,28],[70,72]]:[[20,25],[78,27],[25,73],[78,73]];
  const slot=slots.findIndex((_,i)=>!targets.some(t=>t.slot===i));
  const [x,y]=slots[slot];createTarget(word,x,y,false,slot);return true;
}
function remove(t){targets=targets.filter(x=>x!==t);t.el.remove();}
function hit(t){if(state!=='playing'||t.hit||!targets.includes(t))return;t.hit=true;const pts=pointsFor(t.word);score+=pts;readWords.push(t.word.text);const x=t.el.style.left,y=t.el.style.top;const burst=document.createElement('span');burst.className='burst';burst.textContent=`✦ +${pts}`;burst.style.left=x;burst.style.top=y;$('#field').append(burst);setTimeout(()=>burst.remove(),1000);if(!reduced)for(let i=0;i<9;i++){const dot=document.createElement('i');dot.className='confetti';dot.style.cssText=`left:${x};top:${y};background:${['#e5b547','#75a771','#e69b86','#87bfce'][i%4]};--dx:${Math.cos(i*2.4)*65}px;--dy:${Math.sin(i*2.4)*65}px`;$('#field').append(dot);setTimeout(()=>dot.remove(),900);}remove(t);updateStats();status(demo?'Plopp! So funktioniert das Spiel.':'Prima gelesen! Such dir das nächste Wort.',`„${t.word.text}“ · +${pts} Punkte${demo?' · Demo':''}`);}
function onSpeech(text,details){
  if(state!=='playing'||demo||!text)return;
  const result=attempt.final(text,details,targets,performance.now());
  result.hits.forEach(hit);
  if(result.pending&&!result.hits.length)status('Ich höre weiter … Lass dir Zeit.', 'Gehört: „'+text+'“ · Du kannst das Wort in Ruhe zu Ende lesen.');
}
function onPartial(text){
  if(state!=='playing'||demo||!text)return;
  if(attempt.partial(text,targets,performance.now()))status('Ich höre weiter … Lass dir Zeit.', 'Ich höre: „'+text+'“ …');
}
function checkReadingPause(now){
  if(demo)return;
  const expired=attempt.expire(now);
  if(expired&&!expired.hadHit)status('Das habe ich noch nicht sicher verstanden.', 'Lies ein sichtbares Wort noch einmal in Ruhe vor.');
}
function errorText(error){if(error.name==='NotAllowedError')return 'Der Mikrofonzugriff ist nicht erlaubt. Gib ihn in den Website-Einstellungen deines Browsers frei und versuche es erneut.';if(error.name==='NotFoundError')return 'Kein Mikrofon gefunden. Verbinde ein Mikrofon und versuche es erneut.';if(error.name==='NotReadableError')return 'Das Mikrofon ist gerade nicht verfügbar. Prüfe, ob eine andere App es verwendet.';return error.message||'Die Spracherkennung konnte nicht gestartet werden.';}
function fail(message){session++;speech.stop();attempt.reset();state='paused';$('#pause-panel').hidden=false;$('#pause-panel h2').textContent='Das Mikrofon braucht Hilfe.';$('#pause-panel p').textContent=message;$('#pause').disabled=true;$('#resume').disabled=false;$('#loading').hidden=true;document.body.classList.remove('listening');status('Spiel pausiert. Dein Punktestand bleibt erhalten.',message);}
async function start(isDemo=false,resume=false){if(state==='loading'||state==='playing')return;const ticket=++session;attempt.reset();demo=isDemo;state='loading';locks(true);$('#error').hidden=true;$('#start').disabled=true;$('#demo').disabled=true;$('#resume').disabled=true;$('#loading').hidden=isDemo;$('#welcome').hidden=resume;$('#results').hidden=true;$('#pause-panel').hidden=true;$('#pause').disabled=true;
  try{if(!demo){const ready=await speech.start(onSpeech,onPartial,message=>{if(ticket===session){status(message);$('#load-note').textContent=message;}},fail,{words:poolFor(level),vocabularyHelp,pauseMs:attempt.pauseMs});if(ticket!==session||!ready)return;}
    if(ticket!==session)return;
    if(!resume){score=0;remaining=mode==='practice'?0:duration;readWords=[];deck=new WordDeck(level);clearTargets();spawnClock=0;}
    state='playing';document.body.classList.add('round-active');$('#welcome').hidden=true;$('#pause-panel').hidden=true;$('#pause').disabled=false;$('#end').hidden=false;$('#demo-badge').hidden=!demo;document.body.classList.toggle('demo-active',demo);document.body.classList.toggle('listening',!demo);targets.forEach(measure);while(targets.length<targetLimit()&&spawn()){}updateStats();status(demo?'Demo: Lass die Wörter mit einem Klick platzen.':'Ich höre dir zu. Lies ein Wort laut vor.',demo?'In der echten Runde zählt nur deine Stimme.':'Lies langsam, wenn du möchtest. Nach jedem ganzen Wort hilft eine kurze Pause.');lastTime=performance.now();
  }catch(error){if(ticket!==session)return;if(resume){fail(errorText(error));}else{state='idle';locks(false);$('#welcome').hidden=false;$('#error').textContent=errorText(error);$('#error').hidden=false;status('Das Mikrofon ist noch nicht bereit.',errorText(error));}}
  finally{if(ticket===session){$('#start').disabled=false;$('#demo').disabled=false;$('#resume').disabled=false;$('#loading').hidden=true;}}
}
function pause(){if(state!=='playing')return;state='paused';speech.stop();attempt.reset();$('#pause-panel h2').textContent='Eine kleine Lesepause.';$('#pause-panel p').textContent='Atme durch. Deine Wörter warten auf dich.';$('#pause-panel').hidden=false;$('#pause').disabled=true;document.body.classList.remove('listening');status('Pause · Mikrofon ausgeschaltet.','Deine Wörter und Punkte warten auf dich.');}
function finish(){if(!['playing','paused'].includes(state))return;state='results';document.body.classList.remove('round-active');speech.stop();attempt.reset();session++;$('#pause-panel').hidden=true;$('#results').hidden=false;$('#pause').disabled=true;$('#end').hidden=true;document.body.classList.remove('listening');$('#result-label').textContent=demo?'DEMO BEENDET':'GUT GELESEN!';$('#result-title').textContent=readWords.length?'Das hast du toll gemacht!':'Jeder Anfang zählt!';$('#result-text').textContent=`${score} Punkte · ${readWords.length} ${demo?'angeklickte':'erkannte'} Wörter${demo?' · Dein Rekord bleibt unverändert.':''}`;$('#result-words').replaceChildren(...[...new Set(readWords)].map(text=>Object.assign(document.createElement('span'),{textContent:text})));if(!demo&&score>(Number(best[bestKey()])||0)){best[bestKey()]=score;try{localStorage.setItem('moorwords-best-reading-v4',JSON.stringify(best));}catch{}showBest();}status('Runde beendet · Mikrofon ausgeschaltet.','Lust auf noch ein kleines Leseabenteuer?');}
function home(){session++;speech.stop();attempt.reset();state='idle';document.body.classList.remove('round-active');locks(false);$('#welcome').hidden=false;$('#results').hidden=true;$('#pause-panel').hidden=true;$('#demo-badge').hidden=true;$('#end').hidden=true;$('#pause').disabled=true;$('#loading').hidden=true;$('#start').disabled=false;$('#demo').disabled=false;$('#resume').disabled=false;$('#error').hidden=true;$('#load-note').textContent='Beim ersten Start: deutsches Sprachmodell laden (ca. 45 MB).';document.body.classList.remove('listening','demo-active');score=0;remaining=duration;updateStats();preview();status('Dein nächstes Leseabenteuer wartet.','Mikrofon einschalten, ein Wort aussuchen und laut vorlesen.');}
function tick(now){const dt=Math.min((now-lastTime)/1000,.15);lastTime=now;if(state==='playing'){checkReadingPause(now);if(mode==='timed'){remaining=Math.max(0,remaining-dt);updateStats();if(remaining===0)finish();}if(state==='playing'){targets.forEach(t=>{t.age+=dt;if(!reduced)advanceFlight(t,dt,t.bounds);position(t);});spawnClock+=dt;if(spawnClock>1.2){spawn();spawnClock=0;}targets.filter(t=>t.age>=t.lifetime).forEach(remove);if(!deck.remaining&&!targets.length)finish();}}else if(state==='idle'){previewTime+=dt;targets.forEach(t=>{t.age=previewTime;position(t);});}requestAnimationFrame(tick);}
$('#start').onclick=()=>start(false);$('#demo').onclick=()=>start(true);$('#pause').onclick=pause;$('#resume').onclick=()=>start(demo,true);$('#finish').onclick=finish;$('#end').onclick=finish;$('#again').onclick=()=>start(demo);$('#home').onclick=home;$('#cancel-load').onclick=home;
document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(state!=='idle')return;level=Number(b.dataset.level);document.querySelectorAll('[data-level]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});showBest();showGrade();preview();});
function openDialog(content){if(state==='playing')pause();$('#dialog-content').innerHTML=content;$('#dialog').showModal();}
$('#dialog .close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close();};
$('#help').onclick=()=>openDialog(`<span class="tiny-label">SO SPIELST DU MOORWORDS</span><h2>Lesen. Ploppen. Freuen.</h2><ol><li>Wähle deine Lesestufe und starte das Mikrofon.</li><li>Such dir ein Wort auf einem fliegenden Gegenstand aus.</li><li>Lies es laut vor. Du darfst langsam lesen und kurze Pausen machen. Erkannte Wortteile bleiben kurz zusammen; erst vollständige Wörter zählen.</li><li>Das passende Wort platzt – und du bekommst Punkte! Jedes Wort erscheint pro Runde nur einmal. Der kleine Balken zeigt seine verbleibende Zeit. Schwierige Wörter bleiben länger.</li></ol><p>Blaue Wörter sind kniffliger. Große, goldene und violette Wörter sind eine besondere Herausforderung. Die Gegenstände und Wörter werden unabhängig voneinander ausgewählt.</p><p>Es gibt keinen Punktabzug. Unter ⚙ kannst du ohne Rundenzeit üben. Auch dabei fliegen Wörter nach Ablauf ihrer Zeit weiter. Mit der Demo kannst du das Spiel durch Anklicken kennenlernen.</p><p class="note">Die Erkennung kann sich irren, besonders bei Kinderstimmen oder Hintergrundgeräuschen. Sie bewertet keine Aussprache und ersetzt keine Leseförderdiagnostik.</p>`);
$('#curriculum').onclick=()=>{const grade=GRADES.find(g=>g.id===level);const pool=poolFor(level);const focuses=[...new Set(pool.map(w=>w.focus))];openDialog(`<span class="tiny-label">KLASSE ${level} · ${pool.length} ÜBUNGSWÖRTER</span><h2>${grade.name}</h2><p>${grade.goal}</p><ul>${focuses.map(f=>'<li>'+f+'</li>').join('')}</ul><p><strong>Beispiele:</strong> ${grade.examples.join(', ')}</p><details><summary>Alle Wörter dieser Klasse</summary><p>${pool.map(w=>w.text).join(' · ')}</p></details><p class="note">Die Klassen sind eine Orientierung: Wähle nach dem Lesestand des Kindes. Die Wortauswahl ist eigenständig zusammengestellt und an Grundschul-Lernzielen orientiert, keine amtliche Klassenwortliste. Geübt wird das Wortlesen, nicht das gesamte Leseverständnis oder die Rechtschreibung.</p><p class="note">Grundlagen: <a href="https://www.kmk.org/fileadmin/Dateien/veroeffentlichungen_beschluesse/2022/2022_06_23-Bista-Primarbereich-Deutsch.pdf" target="_blank" rel="noreferrer">KMK Deutsch</a> · <a href="https://www.bildung-lsa.de/informationsportal/unterricht/grundschule/schulformbezogene_informationen/lehrplan.html" target="_blank" rel="noreferrer">Lehrplan Sachsen-Anhalt</a> · <a href="https://zsl-bw.de/,Lde/Startseite/allgemein-bildende-schulen/grundwortschatz-deutsch-gs" target="_blank" rel="noreferrer">Grundwortschatz ZSL</a></p>`);};
$('#privacy').onclick=()=>openDialog(`<span class="tiny-label">DEINE STIMME BLEIBT BEI DIR</span><h2>Lokal lesen lernen.</h2><p>Die Spracherkennung läuft mit Vosk direkt im Browser auf deinem Gerät. Die App überträgt keine Mikrofonaufnahmen und keine erkannten Wörter an einen Server. Aufnahmen werden nicht gespeichert.</p><p>Beim ersten Mikrofonstart werden Programmcode von jsDelivr und ein deutsches Sprachmodell von GitHub Pages geladen. Schriftarten kommen von Google Fonts. Diese Anbieter erhalten normale Downloadanfragen (unter anderem deine IP-Adresse), aber kein Sprachmaterial.</p><p>Vosk kann das Modell im Browser zwischenspeichern. Die App speichert nur deinen Rekord pro Lesestufe und Spielmodus lokal. Eine vollständig offline installierbare Version ist noch nicht enthalten.</p><p>In Pausen, nach einer Runde und beim Verlassen wird das Mikrofon ausgeschaltet.</p><p class="note"><a href="https://github.com/ccoreilly/vosk-browser" target="_blank" rel="noreferrer">Vosk Browser</a> · <a href="https://alphacephei.com/vosk/models" target="_blank" rel="noreferrer">Deutsches Modell</a> · Apache 2.0</p>`);
$('#settings').onclick=()=>{openDialog(`<span class="tiny-label">DEIN SPIEL, DEIN TEMPO</span><h2>Mach es dir passend.</h2><label>Spielmodus<select id="mode-select"><option value="timed">Punkterunde mit Zeit</option><option value="practice">Entspannt üben · ohne Zeitlimit</option></select></label><label>Rundenlänge<select id="duration-select"><option value="60">1 Minute</option><option value="90">1½ Minuten</option><option value="120">2 Minuten</option><option value="180">3 Minuten</option></select></label><label>Wartezeit für zusammengehörige Wortteile<select id="pause-select"><option value="1200">Kurz · 1,2 Sekunden</option><option value="2000">Normal · 2 Sekunden</option><option value="3000">Geduldig · 3 Sekunden</option></select></label><label><input id="vocabulary-setting" type="checkbox">Wortschatzhilfe für die gewählte Klasse</label><p class="note">Die Wartezeit verbindet bereits erkannte Wortteile und verzögert die Rückmeldung. Bleibt eine vorläufige Erkennung so lange unverändert, wird ein endgültiges Ergebnis angefordert. Die Wortschatzhilfe kann helfen, ist aber keine Garantie für richtige Treffer. Zum Vergleich kannst du sie ausschalten.</p><label><input id="motion-setting" type="checkbox">Ruhige Wörter · ohne Flugbewegung</label><p class="note">Klasse 1: vertraute Wörter und Silben. Klasse 2: Buchstabengruppen und Wortformen. Klasse 3: Zusammensetzungen und Wortbausteine. Klasse 4: anspruchsvoller Alltags- und Sachwortschatz. Jede Klasse hat einen eigenen Wortpool. In jeder Klasse sind Wörter im Schnitt 100 Punkte wert. Länge und Lesehürde bestimmen den Bonus oder Abschlag innerhalb der Klasse. Vergleiche Runden mit gleichen Einstellungen.</p><button class="primary" id="save-settings">Übernehmen</button>`);$('#mode-select').value=mode;$('#duration-select').value=String(duration);$('#motion-setting').checked=reduced;$('#pause-select').value=String(attempt.pauseMs);$('#vocabulary-setting').checked=vocabularyHelp;$('#save-settings').onclick=()=>{mode=$('#mode-select').value;duration=Number($('#duration-select').value);reduced=$('#motion-setting').checked;attempt.setPause($('#pause-select').value);vocabularyHelp=$('#vocabulary-setting').checked;remaining=duration;updateStats();showBest();preview();$('#dialog').close();};};
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(state==='playing')pause();else if(state==='loading')home();}});
window.addEventListener('pagehide',()=>speech.dispose());new ResizeObserver(()=>targets.forEach(t=>{measure(t);position(t);})).observe($('#field'));document.fonts.ready.then(()=>targets.forEach(t=>{measure(t);position(t);}));
document.addEventListener('keydown',e=>{if(e.code==='Space'&&state==='playing'&&!['BUTTON','SELECT','INPUT'].includes(e.target.tagName)){e.preventDefault();pause();}});
document.querySelectorAll('[data-level]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.level)===level)));
showBest();showGrade();updateStats();preview();requestAnimationFrame(tick);
